update progressnotedetail set 
updatedon = now(),
updatedby = 'CDM-10089',
description = '<p>Due to SSA reissuing virtual visits because of COVID-19, this worker completed a virtual visit with Amanda. During the visit, Whitney was in the background talking on the phone with her mother.</p><p><br></p><p>Amanda stated that Whitney completed her substance abuse assessment and her UA results should be back next Tuesday. Susan told Whitney that she is not recommending ongoing substance abuse counseling pending her UA results. Worker informed. Worker informed her that if Susan tells the worker that services are not recommended for Whitney, the worker will staff this case with a supervisor to see if there is anything else that should be on a service plan, or if the case can be closed. Worker asked if she thinks there is anything else that the family needs help with or needs to be on a service plan and she stated no. Worker stated that the worker will update the service plan for a week to state that Whitney will continue to comply with the substance abuse assessment in case there is anything else that comes up that she needs to do, and comply with all recommendations. </p><p><br></p><p>Worker scheduled next virtual visit for 2-11-2021 at 4:30 so the worker can see all of the children.</p>'
where progressnotedetailid = '70ff52dd-bcb8-42f1-813d-cbda74691eac';

